import java.util.HashSet;
import java.util.Scanner;

public class Main {
    static long[] parent = new long[1100000];

    static long findParent(long x) {
        if (parent[(int) x] == x) return x;
        parent[(int) x] = findParent(parent[(int) x]);
        return parent[(int) x];
    }

    static void unite(long x, long y) {
        long px = findParent(x);
        long py = findParent(y);
        if (px == py) return;
        parent[(int) px] = py;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        for (long i = 0; i < p; i++) {
            parent[(int) i] = i;
        }

        for (long i = 1; i < p; i++) {
            if ((k * i) % p != 0) {
                unite((k * i) % p, i);
            }
        }

        HashSet<Long> components = new HashSet<>();
        for (long i = 1; i < p; i++) {
            components.add(findParent(i));
        }

        long cycleCount = components.size();
        if (k == 1) cycleCount = p;

        long result = 1;
        long mod = 1000000007;
        for (long i = 0; i < cycleCount; i++) {
            result = (result * p) % mod;
        }

        System.out.println(result);
        sc.close();
    }
}
